function c(r){const n=[];for(const o of r.split(/\r?\n/)){const t=o.trim();if(!t||t.startsWith("#")||t.startsWith("-"))continue;let e=t.split(";")[0].trim();e=e.split(" #")[0].trim();const s=/^([A-Za-z0-9][A-Za-z0-9._-]*)/.exec(e);if(!s)continue;const i=s[1];/[A-Za-z]/.test(i)&&n.push(i)}return[...new Set(n)]}const u="requirements.txt";export{u as REQUIREMENTS_FILE,c as parseRequirements};
